const fileNameCheck = (file_name) => {
  const parts = file_name.split('.');
  if (parts.length !== 2) return 'No';
  const [before, after] = parts;
  if (before.length === 0) return 'No';
  if (!/^[a-zA-Z]/.test(before)) return 'No';
  if (!['txt', 'exe', 'dll'].includes(after)) return 'No';
  const digitCount = (before + after).split('').filter(c => c >= '0' && c <= '9').length;
  if (digitCount > 3) return 'No';
  return 'Yes';
};
