const orderByPoints = (nums) => {
  const digitSum = (n) => {
    n = Math.abs(n);
    let sum = 0;
    while (n > 0) {
      sum += n % 10;
      n = Math.floor(n / 10);
    }
    return sum;
  };
  return nums.map((n, i) => ({ n, i }))
    .sort((a, b) => digitSum(a.n) - digitSum(b.n) || a.i - b.i)
    .map(x => x.n);
};
