  let maxWord = "";
  let maxUnique = -1;

  for (const word of words) {
    const uniqueCount = new Set(word).size;
    if (uniqueCount > maxUnique || (uniqueCount === maxUnique && word < maxWord)) {
      maxUnique = uniqueCount;
      maxWord = word;
    }
  }

  return maxWord;
};

